use crate::io::util::poll_proceed_and_make_progress;
use crate::io::AsyncWrite;

use bytes::Buf;
use pin_project_lite::pin_project;
use std::future::Future;
use std::io::{self, IoSlice};
use std::marker::PhantomPinned;
use std::pin::Pin;
use std::task::{Context, Poll};

pin_project! {
    /// A future to write some of the buffer to an `AsyncWrite`.
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct WriteAllBuf<'a, W, B> {
        writer: &'a mut W,
        buf: &'a mut B,
        #[pin]
        _pin: PhantomPinned,
    }
}

/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write_all_buf<'a, W, B>(writer: &'a mut W, buf: &'a mut B) -> WriteAllBuf<'a, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    WriteAllBuf {
        writer,
        buf,
        _pin: PhantomPinned,
    }
}

impl<W, B> Future for WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        const MAX_VECTORED_CHUNKS: usize = 64;

        let me = self.project();

        match crate::trace::trace_leaf(cx) {
            Poll::Pending => {
                return Poll::Pending;
            }
            Poll::Ready(()) => {
                let mut is_write_vectored = true;
                loop {
                    if !me.buf.has_remaining() {
                        return Poll::Ready(Ok(()));
                    }

                    if is_write_vectored {
                        is_write_vectored = me.writer.is_write_vectored();
                    }

                    let poll_result = if is_write_vectored {
                        let mut slices = [IoSlice::new(&[]); MAX_VECTORED_CHUNKS];
                        let filled = me.buf.chunks_vectored(&mut slices);

                        Pin::new(&mut *me.writer).poll_write_vectored(cx, &slices[..filled])
                    } else {
                        let chunk = me.buf.chunk();

                        Pin::new(&mut *me.writer).poll_write(cx, chunk)
                    };

                    let n = match poll_result {
                        Poll::Pending => {
                            return Poll::Pending;
                        }
                        Poll::Ready(result) => match result {
                            Err(err) => {
                                return Poll::Ready(Err(err));
                            }
                            Ok(written) => written,
                        },
                    };

                    me.buf.advance(n);

                    if n == 0 {
                        let zero_kind = io::ErrorKind::WriteZero;
                        let zero_err = io::Error::from(zero_kind);
                        return Poll::Ready(Err(zero_err));
                    }
                }
            }
        }
    }
}

